 async function togglePublish(item:Item){setBusy(true);setError('');setNotice('');try{const next=text(item.status)==='PUBLISHED'?'DRAFT':'PUBLISHED';await request('/admin/'+active+'/'+encodeURIComponent(item.id),{method:'PATCH',body:JSON.stringify({status:next})});await revalidatePublic();setNotice(next==='PUBLISHED'?'Published. “'+displayName(item)+'” is live on the website now.':'Moved “'+displayName(item)+'” back to draft. It is hidden from the website.');await load()}catch(e){if(e instanceof ApiError&&e.status===401)unauthorized();setError(errorText(e))}finally{setBusy(false)}}
 async function remove(){if(!deleting)return;setBusy(true);try{await request('/admin/'+active+'/'+encodeURIComponent(deleting.id),{method:'DELETE'});await revalidatePublic();setDeleting(null);setNotice('Record deleted.');await load()}catch(e){if(e instanceof ApiError&&e.status===401)unauthorized();setError(errorText(e));setDeleting(null)}finally{setBusy(false)}}
 /* Menu badges: waiting inquiries and support requests, refreshed every minute. */
