 async function upload(file:File){setBusy(true);setError('');try{if(file.size>5*1024*1024)throw Error('Maximum upload size is 5 MB.');const data=new FormData();data.append('file',file);await request('/admin/media',{method:'POST',body:data});setNotice('File uploaded successfully.');await load()}catch(e){if(e instanceof ApiError&&e.status===401)unauthorized();setError(errorText(e))}finally{setBusy(false)}}
 if(checking)return <main className="adm-auth"><h1 className="adm-sr-only">WSJ Studio administration</h1><div className="adm-loading" role="status"><RefreshCw className="adm-spin"/> Checking your session…</div></main>;
 if(!user)return <main className="adm-auth"><div className="adm-auth-story" data-ui-tone="dark"><Link className="adm-brand" href="/"><span className="adm-mark">W</span>WSJ<span className="adm-brand-dot">.</span></Link><div><span className="adm-eyebrow">YOUR DIGITAL COMMAND CENTER</span><h1>Great work starts<br/>behind the scenes.</h1><p>Manage your content, connect with your audience,<br/>and keep everything moving forward.</p></div><small>WSJ Studio · Content management</small></div><div className="adm-auth-panel"><form onSubmit={login} className="adm-login"><span className="adm-eyebrow">WELCOME BACK</span><h2>Sign in to your workspace</h2><p>Use your administrator credentials to continue.</p><Field label="Email address"><input name="email" type="email" required autoComplete="username" placeholder="you@company.com"/></Field><Field label="Password"><input name="password" type="password" required autoComplete="current-password" placeholder="Enter your password"/></Field>{authError&&<div className="adm-alert" role="alert">{authError}</div>}<button className="adm-button adm-primary" disabled={logging}>{logging?'Signing in…':'Sign in'}<ArrowUpRight size={18}/></button><button type="button" className="adm-text-button" onClick={()=>void checkAuth()}>Retry session check</button><small>Secure access. Authorized team members only.</small></form></div></main>;
 const current=resources.find(r=>r.key===active),isDashboard=active==='dashboard',canWrite=user.role!=='VIEWER',canManage=user.role==='ADMIN',catalogView=isCatalogKey(active)?catalogViews[active]:null;
 const visibleResources=resources.filter(r=>canManage||!['users','settings','audit','kisi','workspace-clone'].includes(r.key));
 const navTitle=(r?:{key:string;label:string;icon:never}|typeof resources[number])=>r?navLabel(r as never):'';
 const fmtDate=(v:unknown)=>v?new Date(text(v)).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
 const pill=(s:string)=><span className={'adm-pill is-'+s.toLowerCase().replace(/[^a-z]/g,'')}>{s[0]+s.slice(1).toLowerCase()}</span>;
