 function tableColumns(key:string):Column[]{
  const created:Column={key:'created',label:'Created',sort:'created',optional:true,hiddenByDefault:key!=='inquiries',render:r=>fmtDate(r.createdAt),csv:r=>text(r.createdAt)};
  const updated:Column={key:'updated',label:'Updated',sort:'updated',optional:true,render:r=>fmtDate(r.updatedAt||r.createdAt),csv:r=>text(r.updatedAt||r.createdAt)};
  if(key==='inquiries')return [
   {key:'contact',label:'Contact',sort:'name',render:r=><div className="adm-cell-main"><strong>{text(r.name)||'—'}</strong><small>{text(r.email)}</small>{Array.isArray(r.tags)&&r.tags.length>0&&<div className="adm-tagdots">{(r.tags as string[]).slice(0,3).map(t=><span key={t}>{t}</span>)}</div>}</div>,csv:r=>text(r.name)+' <'+text(r.email)+'>'},
   {key:'message',label:'Message',optional:true,render:r=><span className="adm-cell-clip">{text(r.message)}</span>,csv:r=>text(r.message)},
   {key:'service',label:'Service',optional:true,hiddenByDefault:true,render:r=>text(r.service)||'—',csv:r=>text(r.service)},
   {key:'status',label:'Status',sort:'status',render:r=>pill(STEPS.find(s=>s[0]===stepOf(text(r.status)))?.[0]||text(r.status)),csv:r=>stepOf(text(r.status))},
   {key:'assigned',label:'Handled by',optional:true,hiddenByDefault:true,render:r=>text(r.assignedTo)||'—',csv:r=>text(r.assignedTo)},
   {...created,label:'Received'},updated];
  if(contentResources.includes(key))return [
   {key:'title',label:'Title',sort:'title',render:r=><div className="adm-cell-main"><strong>{displayName(r as Item)}</strong><small>/{text(r.slug)}</small></div>,csv:r=>displayName(r as Item)},
   {key:'summary',label:'Summary',optional:true,render:r=><span className="adm-cell-clip">{text(r.excerpt)||'—'}</span>,csv:r=>text(r.excerpt)},
   {key:'status',label:'Status',sort:'status',render:r=>pill(statusOf(r as Item)),csv:r=>statusOf(r as Item)},
   updated,created];
  return [
   {key:'name',label:['audit','popup-events'].includes(key)?'Activity':'Name',render:r=><div className="adm-cell-main"><strong>{displayName(r as Item)}</strong><small>{text(r.email||r['customerEmail']||r.slug||r.id)}</small></div>,csv:r=>displayName(r as Item)},
   {key:'details',label:['audit','popup-events'].includes(key)?'Resource':key==='users'?'Role':key==='bookings'?'Service':'Details',optional:true,render:r=><span className="adm-cell-clip">{text(key==='popup-events'?r.popupId:key==='audit'?r.resource:key==='users'?r.role:key==='bookings'?r['serviceName']:r.excerpt||r.mimeType||'—')}</span>,csv:r=>text(key==='audit'?r.resource:key==='users'?r.role:key==='bookings'?r['serviceName']:r.excerpt||'')},
   {key:'status',label:'Status',render:r=>pill(statusOf(r as Item)),csv:r=>statusOf(r as Item)},
   updated,created];
 }
 function bulkFor(key:string):BulkAction[]{
  if(key==='inquiries')return [
   {id:'contacted',label:'Mark contacted',run:async ids=>{const r=await request<{updated:number}>('/admin/inquiries/bulk',{method:'POST',body:JSON.stringify({ids,status:'CONTACTED'})});return r.updated+' marked contacted.'}},
   {id:'closed',label:'Close',run:async ids=>{const r=await request<{updated:number}>('/admin/inquiries/bulk',{method:'POST',body:JSON.stringify({ids,status:'CLOSED'})});return r.updated+' closed.'}}];
  if(contentResources.includes(key)&&key!=='blog')return [
   {id:'publish',label:'Publish',run:async ids=>{const r=await request<{updated:number}>('/admin/'+key+'/bulk',{method:'POST',body:JSON.stringify({ids,action:'publish'})});void revalidatePublic();return r.updated+' published.'}},
   {id:'draft',label:'Unpublish',run:async ids=>{const r=await request<{updated:number}>('/admin/'+key+'/bulk',{method:'POST',body:JSON.stringify({ids,action:'draft'})});void revalidatePublic();return r.updated+' moved to draft.'}},
   {id:'archive',label:'Archive',danger:true,run:async ids=>{const r=await request<{updated:number}>('/admin/'+key+'/bulk',{method:'POST',body:JSON.stringify({ids,action:'archive'})});void revalidatePublic();return r.updated+' archived.'}}];
  return [];
 }

